(()=>{
 const panel=document.createElement('details');panel.id='lifetime-panel';panel.className='advanced';panel.innerHTML='<summary>Lifetime curves & color gradient</summary><p class="animation-intro">Shape each particle from birth (0%) to death (100%). Curves replace the matching start/end lifetime control. Layer timeline animation still applies.</p>';
 const choice=document.createElement('select');choice.id='lifetime-property';choice.setAttribute('aria-label','Lifetime property');for(const [value,label]of [['size','Size multiplier'],['opacity','Opacity'],['color','Color gradient']])choice.add(new Option(label,value));panel.append(choice);
 const enableLabel=document.createElement('label');enableLabel.textContent='Use this curve';const enable=document.createElement('input');enable.type='checkbox';enable.id='lifetime-enabled';enableLabel.append(enable);panel.append(enableLabel);
 const svg=document.createElementNS('http://www.w3.org/2000/svg','svg');svg.id='lifetime-graph';svg.setAttribute('viewBox','0 0 280 110');svg.setAttribute('role','img');svg.setAttribute('aria-label','Lifetime curve from birth to death');svg.style.cssText='width:100%;height:110px;background:#17151e;border-radius:8px';panel.append(svg);
 const rows=document.createElement('div');rows.id='lifetime-stops';panel.append(rows);const add=document.createElement('button');add.id='lifetime-add-stop';add.textContent='Add stop halfway through largest gap';panel.append(add);const recipes=document.createElement('div');recipes.className='dynamics-recipes';panel.append(recipes);
 function defaults(key){return key==='size'?[{time:0,value:1},{time:1,value:state.endSize??1}]:key==='opacity'?[{time:0,value:0},{time:.125,value:1},{time:1,value:state.endOpacity??0}]:[{time:0,value:state.color},{time:1,value:state.endColor||state.color}];}
 function save(){EmberLifetime.validate(state.lifetime);persist();}
 enable.onchange=()=>{state.lifetime={...state.lifetime};if(enable.checked)state.lifetime[choice.value]=defaults(choice.value);else delete state.lifetime[choice.value];save();refresh();};choice.onchange=refresh;
 add.onclick=()=>{const points=state.lifetime[choice.value];let gap=0;for(let i=1;i<points.length;i++)if(points[i].time-points[i-1].time>points[gap+1].time-points[gap].time)gap=i-1;const time=(points[gap].time+points[gap+1].time)/2,value=EmberLifetime.sample(points,time,EmberAnimation.mix);points.splice(gap+1,0,{time,value});save();refresh();};
 for(const [name,curves]of [['Grow & dissolve',{size:[{time:0,value:.1},{time:.35,value:1.5},{time:1,value:3}],opacity:[{time:0,value:0},{time:.12,value:1},{time:.6,value:.7},{time:1,value:0}]}],['Hot spark gradient',{color:[{time:0,value:'#ffffff'},{time:.2,value:'#ffe388'},{time:.6,value:'#ff7518'},{time:1,value:'#530917'}]}]]){const button=document.createElement('button');button.textContent=name;button.onclick=()=>{state.lifetime={...state.lifetime,...structuredClone(curves)};save();refresh();};recipes.append(button);}
 function draw(points,key){svg.replaceChildren();if(key==='color'){for(let i=0;i<70;i++){const rect=document.createElementNS(svg.namespaceURI,'rect');rect.setAttribute('x',10+i*260/70);rect.setAttribute('y',20);rect.setAttribute('width',260/70+1);rect.setAttribute('height',65);rect.setAttribute('fill',EmberLifetime.sample(points,i/69,EmberAnimation.mix));svg.append(rect);}return;}const maximum=key==='size'?Math.max(1,...points.map(p=>p.value)):1,path=document.createElementNS(svg.namespaceURI,'polyline');path.setAttribute('points',points.map(p=>`${10+p.time*260},${95-p.value/maximum*80}`).join(' '));path.setAttribute('fill','none');path.setAttribute('stroke','#c4a5ff');path.setAttribute('stroke-width',3);svg.append(path);for(const p of points){const dot=document.createElementNS(svg.namespaceURI,'circle');dot.setAttribute('cx',10+p.time*260);dot.setAttribute('cy',95-p.value/maximum*80);dot.setAttribute('r',4);dot.setAttribute('fill','#fff');svg.append(dot);}}
 function refresh(){const key=choice.value,points=state.lifetime?.[key];enable.checked=!!points;rows.replaceChildren();svg.style.display=points?'block':'none';add.disabled=!points||points.length>=8;if(!points)return;draw(points,key);points.forEach((point,index)=>{const row=document.createElement('div');row.style.cssText='display:grid;grid-template-columns:48px 12px minmax(45px,1fr) 60px;gap:4px;margin:8px 0;align-items:center';const age=document.createElement('input');age.type='number';age.min=index?points[index-1].time*100+.01:0;age.max=index<points.length-1?points[index+1].time*100-.01:100;age.step='any';age.value=point.time*100;age.disabled=index===0||index===points.length-1;age.setAttribute('aria-label','Stop '+(index+1)+' age percent');age.style.cssText='width:100%;min-width:0;padding:8px 4px';age.onchange=()=>{if(!age.checkValidity()||!Number.isFinite(age.valueAsNumber)){age.value=point.time*100;return;}point.time=age.valueAsNumber/100;save();refresh();};const value=document.createElement('input');value.type=key==='color'?'color':'number';if(key!=='color'){value.min=0;value.max=key==='size'?5:1;value.step='any';}value.value=point.value;value.setAttribute('aria-label','Stop '+(index+1)+' '+key);value.style.cssText='width:100%;min-width:0;padding:8px 4px';value.oninput=()=>{if(!value.checkValidity()||key!=='color'&&!Number.isFinite(value.valueAsNumber))return;point.value=key==='color'?value.value:value.valueAsNumber;save();draw(points,key);};const percent=document.createElement('span');percent.textContent='%';row.append(age,percent,value);if(index&&index<points.length-1){const remove=document.createElement('button');remove.textContent='Remove';remove.style.cssText='padding:8px 4px;font-size:11px;min-width:0';remove.onclick=()=>{points.splice(index,1);save();refresh();};row.append(remove);}rows.append(row);});}
 $('#animation-panel').before(panel);const previous=sync;sync=()=>{previous();refresh();};refresh();
})();
